    for mate in ['forward','reverse']:
        p=d/mate/(mate+'.fastqsanger.gz')
        qcols=[[] for _ in range(251)]
        with gzip.open(p,'rt') as h:
            for j in range(5000):
                h.readline(); h.readline(); h.readline(); q=h.readline().strip()
                for i,c in enumerate(q): qcols[i].append(ord(c)-33)
        print(d.name,mate)
        for i in [0,1,2,9,24,49,99,149,199,219,229,239,244,249,250]:
            if qcols[i]:
                a=sorted(qcols[i]); n=len(a)
                def q(x): return a[min(n-1,int(x*(n-1)))]
                print(i+1, 'med',q(.5),'p10',q(.1),'p25',q(.25),'p75',q(.75),'p90',q(.9),'frac>=30',sum(v>=30 for v in a)/n)
PY"

